def frames(lines):
    results = []
    current_data = []

    for line in lines:
        if line == "":
            if current_data:
                results.append("\n".join(current_data))
            current_data = []
        elif line.startswith(":"):
            continue
        else:
            colon_idx = line.find(":")
            if colon_idx == -1:
                continue
            field = line[:colon_idx]
            if field == "data":
                value = line[colon_idx + 1:]
                if value.startswith(" "):
                    value = value[1:]
                current_data.append(value)

    return results
```

