import copy


def merge(base, overlay):
    """Recursively merge two JSON-like dictionaries.

    Overlay values replace base values (including lists and None).
    A None value in overlay does not delete the key; it replaces the value.
    Returns a new dict with no shared references to input data.
    """
    result = {}
    for key in base:
        if key in overlay:
            if isinstance(base[key], dict) and isinstance(overlay[key], dict):
                result[key] = merge(base[key], overlay[key])
            else:
                result[key] = copy.deepcopy(overlay[key])
        else:
            result[key] = copy.deepcopy(base[key])
    for key in overlay:
        if key not in base:
            result[key] = copy.deepcopy(overlay[key])
    return result
```

