def flatten(value):
    if not isinstance(value, dict):
        return value
    result = {}
    for key, sub in value.items():
        if isinstance(sub, dict):
            if sub:
                for k, v in flatten(sub).items():
                    result["{}.{}".format(key, k)] = v
            else:
                result[key] = {}
        else:
            result[key] = sub
    return result
