from collections import deque

def admit(times, limit, window):
    if limit < 1 or window < 1:
        raise ValueError("limit and window must be >= 1")

    result = []
    accepted = deque()

    for t in times:
        while accepted and accepted[0] <= t - window:
            accepted.popleft()

        if len(accepted) < limit:
            result.append(True)
            accepted.append(t)
        else:
            result.append(False)

    return result
