import heapq


def order(deps):
    # Collect all nodes (keys + any prerequisite-only nodes)
    all_nodes = set(deps.keys())
    for prereqs in deps.values():
        all_nodes.update(prereqs)

    # Build prerequisite sets (as sets to avoid double-counting duplicates)
    prereqs_map = {}
    for node in all_nodes:
        prereqs_map[node] = set(deps[node]) if node in deps else set()

    # Build reverse adjacency: for each prereq, which nodes depend on it
    dependents = {node: [] for node in all_nodes}
    for node in all_nodes:
        for p in prereqs_map[node]:
            dependents[p].append(node)

    # In-degree = number of unsatisfied prerequisites
    in_degree = {node: len(prereqs_map[node]) for node in all_nodes}

    # Min-heap of currently ready nodes
    heap = [node for node in all_nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for dep in dependents[node]:
            in_degree[dep] -= 1
            if in_degree[dep] == 0:
                heapq.heappush(heap, dep)

    if len(result) != len(all_nodes):
        raise ValueError("cycle detected")

    return result
```

